sheet.addEventListener('pointerdown',e=>{if(e.button!==0)return;if(e.target.closest('input,select,.dynasty-name,.dynasty-event')){suppressUntil=0;return;}const r=sheet.querySelector('.dynasty-track').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)return;e.preventDefault();e.stopPropagation();ctx.stop();pointer=e.pointerId;suppressUntil=performance.now()+1000;sheet.classList.add('is-scrubbing');document.documentElement.classList.add('timeline-scrubbing');cursor.focus({preventScroll:true});sheet.setPointerCapture(pointer);queue(e);},true);
