cursor.setAttribute('aria-valuemin',axis.minAxis);cursor.setAttribute('aria-valuemax',axis.maxAxis);cursor.title='拖动游标或时间图任意位置选年；左右方向键逐年，上下方向键换代，Home／End到两端';cursor.setAttribute('aria-keyshortcuts','ArrowLeft ArrowRight ArrowUp ArrowDown Home End');function keyYear(e){if(e.isComposing||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)return;if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();e.stopPropagation();moveDynasty(e.key==='ArrowUp'?-1:1);return;}let value;if(e.key==='ArrowLeft')value=nextYear(ctx.getYear(),-1);else if(e.key==='ArrowRight')value=nextYear(ctx.getYear(),1);else if(e.key==='Home')value=axis.minYear;else if(e.key==='End')value=axis.maxYear;else return;e.preventDefault();e.stopPropagation();ctx.stop();ctx.setYear(value);}
